typedef unsigned char u_char;
typedef unsigned int u_int;
typedef unsigned long long u_long;
typedef unsigned int u_long128 __attribute__((mode(TI)));
struct sceGifPacket { u_int* pCurrent; u_int* pBase; };
extern sceGifPacket nglGifPkt;
extern u_char* nglGifPacketWork;
extern "C" void sceGifPkInit(sceGifPacket*, u_long128*);
extern "C" void sceGifPkReset(sceGifPacket*);
extern "C" void sceGifPkAddGsData(sceGifPacket*, u_long);
extern "C" void sceGifPkTerminate(sceGifPacket*);
extern "C" int sceGifPkSize(sceGifPacket*);
extern "C" int FlushCache(int);
extern void _nglDmaSetWaitGif();
extern void _nglDmaWait();
__asm__(".equ nglGifPkt,0x004AEF40");
__asm__(".equ nglGifPacketWork,0x004AEF34");
#define NULL 0
#define WRITEBACK_DCACHE 0
#define SCE_GIF_PACKED 0
#define SCE_GIF_SET_TAG(nloop,eop,pre,prim,flg,nreg) ((u_long)(nloop)|((u_long)(eop)<<15)|((u_long)(pre)<<46)|((u_long)(prim)<<47)|((u_long)(flg)<<58)|((u_long)(nreg)<<60))
#define SCE_GS_SET_PRMODECONT(a) ((u_long)(a))
#define SCE_GS_PRMODECONT 0x1a
#define SCE_GS_PSMCT32 0
#define SCE_GS_SET_FRAME_1(fbp,fbw,psm,fbmsk) ((u_long)(fbp)|((u_long)(fbw)<<16)|((u_long)(psm)<<24)|((u_long)(fbmsk)<<32))
#define SCE_GS_FRAME_1 0x4c
#define SCE_GS_SET_XYOFFSET_1(ofx,ofy) ((u_long)(ofx)|((u_long)(ofy)<<32))
#define SCE_GS_XYOFFSET_1 0x18
#define SCE_GS_SET_SCISSOR_1(x0,x1,y0,y1) ((u_long)(x0)|((u_long)(x1)<<16)|((u_long)(y0)<<32)|((u_long)(y1)<<48))
#define SCE_GS_SCISSOR_1 0x40
#define SCE_GS_SET_TEST_1(ate,atst,aref,afail,date,datm,zte,ztst) ((u_long)(ate)|((u_long)(atst)<<1)|((u_long)(aref)<<4)|((u_long)(afail)<<12)|((u_long)(date)<<14)|((u_long)(datm)<<15)|((u_long)(zte)<<16)|((u_long)(ztst)<<17))
#define SCE_GS_TEST_1 0x47
#define SCE_GS_PRIM_SPRITE 6
#define SCE_GS_SET_PRIM(prim,iip,tme,fge,abe,aa1,fst,ctxt,fix) ((u_long)(prim)|((u_long)(iip)<<3)|((u_long)(tme)<<4)|((u_long)(fge)<<5)|((u_long)(abe)<<6)|((u_long)(aa1)<<7)|((u_long)(fst)<<8)|((u_long)(ctxt)<<9)|((u_long)(fix)<<10))
#define SCE_GS_PRIM 0
#define SCE_GS_SET_RGBAQ(r,g,b,a,q) ((u_long)(r)|((u_long)(g)<<8)|((u_long)(b)<<16)|((u_long)(a)<<24)|((u_long)(q)<<32))
#define SCE_GS_RGBAQ 1
#define SCE_GS_SET_XYZ(x,y,z) ((u_long)(x)|((u_long)(y)<<16)|((u_long)(z)<<32))
#define SCE_GS_XYZF2 4
#define NGL_DMA_MEM 0x0FFFFFFF
#define D_STAT ((volatile u_int*)0x1000e010)
#define D2_CHCR ((volatile u_int*)0x1000a000)
#define D2_MADR ((volatile u_int*)0x1000a010)
#define D2_QWC ((volatile u_int*)0x1000a020)
#define D2_TADR ((volatile u_int*)0x1000a030)
static inline void sync_l(){ __asm__("sync.l\nnop"); }
#define _nglDmaStartGifNormal(addr,qwc) { sync_l(); *D_STAT=1<<2; *D2_QWC=qwc; *D2_MADR=(u_int)(addr)&NGL_DMA_MEM; *D2_TADR=0x00; *D2_CHCR=1|(0<<2)|(0<<4)|(0<<6)|(0<<7)|(1<<8); sync_l(); }

// Props to George Bain (SCEE) for this function.
void nglClearVRAM( u_char r, u_char g, u_char b, u_char a )
{
  // set base address of GIF packet
  sceGifPkInit(&nglGifPkt, (u_long128*)nglGifPacketWork );
  sceGifPkReset(&nglGifPkt);

  // set GIF tag
  sceGifPkAddGsData(&nglGifPkt, SCE_GIF_SET_TAG(9,1,NULL,NULL,SCE_GIF_PACKED,1));
  sceGifPkAddGsData(&nglGifPkt, 0xEL);

  // enable PRIM register
  sceGifPkAddGsData(&nglGifPkt, SCE_GS_SET_PRMODECONT(1));
  sceGifPkAddGsData(&nglGifPkt, SCE_GS_PRMODECONT);

  // frame buffer settting
  sceGifPkAddGsData(&nglGifPkt, SCE_GS_SET_FRAME_1(0, 1024/64, SCE_GS_PSMCT32, 0));
  sceGifPkAddGsData(&nglGifPkt, SCE_GS_FRAME_1);

  // offset value ( PRIM coord -> WIN coord )
  sceGifPkAddGsData(&nglGifPkt, SCE_GS_SET_XYOFFSET_1(0,0));
  sceGifPkAddGsData(&nglGifPkt, SCE_GS_XYOFFSET_1);

  // scissor settings ( WIN coordinates x0,x1,y0,y1 )
  sceGifPkAddGsData(&nglGifPkt, SCE_GS_SET_SCISSOR_1(0,1024,0,1024));
  sceGifPkAddGsData(&nglGifPkt, SCE_GS_SCISSOR_1);

  // pixel test control
  sceGifPkAddGsData(&nglGifPkt, SCE_GS_SET_TEST_1(0,0,0,0,0,0,0,0));
  sceGifPkAddGsData(&nglGifPkt, SCE_GS_TEST_1);

  // set sprite primitive
  sceGifPkAddGsData(&nglGifPkt, SCE_GS_SET_PRIM(SCE_GS_PRIM_SPRITE,0,0,0,0,0,0,0,0) );
  sceGifPkAddGsData(&nglGifPkt, SCE_GS_PRIM);

  // set RGBA of sprite
  sceGifPkAddGsData(&nglGifPkt, SCE_GS_SET_RGBAQ(r, g, b, a, 0x3f800000));
  sceGifPkAddGsData(&nglGifPkt, SCE_GS_RGBAQ);

  // set upper-left position of sprite
  sceGifPkAddGsData(&nglGifPkt, SCE_GS_SET_XYZ(0,0,0) );
  sceGifPkAddGsData(&nglGifPkt, SCE_GS_XYZF2);

  // set lower-right position of sprite
  sceGifPkAddGsData(&nglGifPkt, SCE_GS_SET_XYZ( 1024<<4, 1024<<4, 0) );
  sceGifPkAddGsData(&nglGifPkt, SCE_GS_XYZF2);

  // get packet size in quad words
  sceGifPkTerminate(&nglGifPkt);

  // DMA send (Normal Mode) to GS via path 3
  FlushCache(WRITEBACK_DCACHE);

  _nglDmaStartGifNormal(((u_int)nglGifPkt.pBase&NGL_DMA_MEM), sceGifPkSize(&nglGifPkt));
  _nglDmaSetWaitGif();
  _nglDmaWait();
}
